// This file is generated by AI.

// 文件变更批次的解析 (纯逻辑, 不认识 Tauri: 存在性查询从外部注入)。
//
// 一次"拷贝一整个立绘文件夹到资源目录"会在一瞬间产生成千上万条事件。原来每条路径都单独
// 查一次存在性、查完立刻转发, 于是: 主线程被大量 IPC 淹没, 语言服务同时收到上千条独立
// 通知 —— 编辑器看起来就是"语言服务卡死, 状态栏还写着就绪" (issue #25 的第三处症状)。
//
// 这里只做两件事:
//
// * 有界并发: 存在性查询按固定并发度批量做完, 而不是一条链一条链地各查各的;
// * 分级降级: 爆发规模超过阈值时不再逐条查询, 直接按事件类型转发 (少一次往返,
//   服务器对"文件已不在"是容错的)。

/** LSP `FileEvent.type`: 1 = 创建, 2 = 修改, 3 = 删除 */
export type FileChangeType = 1 | 2 | 3;

export interface WatchedChange {
  path: string;
  type: FileChangeType;
}

export interface ExistsResult {
  exists: boolean;
  isDirectory: boolean;
}

/** 超过这个规模就不再逐条查询存在性 (一次批量操作往往意味着几百上千次往返) */
export const DEFAULT_MAX_STAT_PATHS = 2048;

/** 存在性查询并发度: 并发太高会把 IPC 与主线程一起压住, 太低又追不上事件 */
export const DEFAULT_STAT_CONCURRENCY = 16;

/**
 * 以固定并发度映射, 并保持结果顺序。
 *
 * 不用 `Promise.all(items.map(...))`: 那会一次性把全部请求拍出去 (成千上万个 IPC) ——
 * 正是要避免的事。
 */
export async function mapLimited<T, R>(items: readonly T[], limit: number, run: (item: T) => Promise<R>): Promise<R[]> {
  const results: R[] = new Array<R>(items.length);
  const workers = Math.max(1, Math.min(limit, items.length));
  let next = 0;

  const worker = async () => {
    for (;;) {
      const index = next++;
      if (index >= items.length) return;
      results[index] = await run(items[index]);
    }
  };

  await Promise.all(Array.from({ length: workers }, worker));
  return results;
}

/**
 * 把"合并后的路径 -> 事件类型"解析成可转发的变更列表。
 *
 * * 删除事件本身就是结论, 不再查询;
 * * 创建 / 修改事件要按**当前磁盘状态**复核: notify 在重命名时只会报 `modify`,
 *   旧路径这时其实已经不存在了, 不复核就会被当成"修改"转发给语言服务; 目录事件不转发
 *   (语言服务只关心文件)。
 * * 规模超过 `maxStatPaths` 时整批跳过复核, 按事件类型原样转发。
 */
export async function resolveChanges(
  batch: Iterable<readonly [string, FileChangeType]>,
  options: {
    exists: (path: string) => Promise<ExistsResult>;
    maxStatPaths?: number;
    concurrency?: number;
  }
): Promise<WatchedChange[]> {
  const entries = [...batch];
  const needCheck = entries.filter(([, type]) => type !== 3);
  const maxStatPaths = options.maxStatPaths ?? DEFAULT_MAX_STAT_PATHS;
  const concurrency = options.concurrency ?? DEFAULT_STAT_CONCURRENCY;

  const checked =
    needCheck.length > maxStatPaths ? null : await mapLimited(needCheck, concurrency, ([path]) => options.exists(path));

  const changes: WatchedChange[] = [];
  // 复核结果与 `needCheck` 同序 (即与"非删除事件"在 `entries` 中的相对顺序一致)
  let next = 0;
  for (const [path, type] of entries) {
    if (type === 3) {
      changes.push({ path, type });
      continue;
    }

    if (!checked) {
      // 超出规模: 不复核, 按事件类型转发
      changes.push({ path, type });
      continue;
    }

    const info = checked[next++];
    if (!info.exists) {
      changes.push({ path, type: 3 });
    } else if (!info.isDirectory) {
      changes.push({ path, type });
    }
  }
  return changes;
}
